            new_board[r][c] = 'Y'
    # Restore the gap in Y platform
    for r in range(48, 54):
        for c in range(52, 55):
            new_board[r][c] = 'b'

    # Move black block
    new_black = set()
    for (r, c) in black_cells:
        nr, nc = r + dr, c + dc
        if 0 <= nr < 64 and 0 <= nc < 64:
            # Can't move into S wall at cols 30-32
            if 30 <= nc <= 32:
                new_black.add((r, c))
            else:
                new_black.add((nr, nc))
        else:
            new_black.add((r, c))

    # Move gray block
    new_gray = set()
    for (r, c) in gray_cells:
        nr, nc = r + dr, c + dc
        if 0 <= nr < 64 and 0 <= nc < 64:
            # Can't move into S wall at cols 30-32
            if 30 <= nc <= 32:
                new_gray.add((r, c))
            else:
