            new_board[r][c] = 'c'

    # Place black block (overwrites gray)
    for (r, c) in new_black:
        if 0 <= r < 64 and 0 <= c < 64:
            new_board[r][c] = 'B'

    # Fix W pattern in black block
    # The W pattern is at specific positions relative to block
    # Find block top-left corner
    if new_black:
        min_r = min(r for r, c in new_black)
