def predict(board_lines, action):
    """
    Predict the next board state given the current board and action.

    Args:
        board_lines: list of 64 strings, each 64 characters long
        action: string, one of UP, DOWN, LEFT, RIGHT, SPACE, UNDO, or MOUSE(r,c)

    Returns:
        list of 64 strings, the complete next board state
    """
    # Convert board to list of lists for easier manipulation
    board = [list(row) for row in board_lines]

    # Find cursor position (leftmost column of the 3-wide sky blue strip)
    cursor_col = None
    for r in range(64):
        for c in range(62):
            if board[r][c] == 'S' and board[r][c+1] == 'S' and board[r][c+2] == 'S':
                cursor_col = c
                break
        if cursor_col is not None:
            break

    if cursor_col is None:
        # Try to find cursor with W in middle (after SPACE)
        for r in range(64):
            for c in range(62):
                if board[r][c] == 'S' and board[r][c+2] == 'S':
                    cursor_col = c
                    break
            if cursor_col is not None:
                break

    if cursor_col is None:
        return board_lines

    # Identify block regions
    # Find left block (charcoal c) top-left corner
    left_block_top, left_block_left = None, None
    for r in range(64):
        for c in range(64):
            if board[r][c] == 'c':
                left_block_top, left_block_left = r, c
                break
        if left_block_top is not None:
            break

    # Find right block (black B) top-left corner
    right_block_top, right_block_left = None, None
    for r in range(64):
        for c in range(64):
            if board[r][c] == 'B' and r > 0 and board[r-1][c] == 'b':
                right_block_top, right_block_left = r, c
                break
        if right_block_top is not None:
            break

    if action == 'DOWN':
        # Move cursor right by 3
        new_cursor_col = min(61, cursor_col + 3)

        # Create new board - start with copy
        new_board = [row[:] for row in board]

        # Move cursor: clear old position, set new position
        for r in range(64):
            # Clear old cursor
            new_board[r][cursor_col] = 'b'
            new_board[r][cursor_col + 1] = 'b'
            new_board[r][cursor_col + 2] = 'b'
            # Set new cursor
            if new_cursor_col + 2 < 64:
                new_board[r][new_cursor_col] = 'S'
                new_board[r][new_cursor_col + 1] = 'S'
                new_board[r][new_cursor_col + 2] = 'S'

        # Update edge column: row 0 changes from B to Y
        if board[0][63] == 'B':
            new_board[0][63] = 'Y'

        # Add white markers at new cursor position (every 3rd row starting from row 1)
        for r in range(1, 64, 3):
            if new_cursor_col + 1 < 64:
                new_board[r][new_cursor_col + 1] = 'W'

        # Check if blocks should move down (cursor was at column 33)
        # Only move blocks down if they've been shifted horizontally before
        # Initial left block position is at column 21 (or 15 after shift)
        # We check if blocks are not at initial position
        blocks_shifted = (left_block_left != 21)

        if cursor_col == 33 and blocks_shifted:
            # Move left block down by 3
            for r in range(60, -1, -1):
                for c in range(64):
                    if board[r][c] in 'cYb':
                        # Check if this is part of left block
                        if board[r][c] == 'c':
                            new_board[r+3][c] = board[r][c]
                            new_board[r][c] = 'b'
                        elif board[r][c] == 'Y' and r >= left_block_top:
                            new_board[r+3][c] = board[r][c]
                            new_board[r][c] = 'b'
                        elif board[r][c] == 'b' and r >= left_block_top and c >= left_block_left - 6:
                            new_board[r+3][c] = board[r][c]
                            new_board[r][c] = 'b'

            # Move right block down by 3
            for r in range(60, -1, -1):
                for c in range(64):
                    if board[r][c] in 'BW':
                        if board[r][c] == 'B' and r >= right_block_top:
                            new_board[r+3][c] = board[r][c]
                            new_board[r][c] = 'b'
                        elif board[r][c] == 'W' and r >= right_block_top:
                            new_board[r+3][c] = board[r][c]
                            new_board[r][c] = 'b'

        return [''.join(row) for row in new_board]

    elif action == 'UP':
        # Move cursor left by 3
        new_cursor_col = max(0, cursor_col - 3)

        # Create new board - start with copy
        new_board = [row[:] for row in board]

        # Move cursor: clear old position, set new position
        for r in range(64):
            new_board[r][cursor_col] = 'b'
            new_board[r][cursor_col + 1] = 'b'
            new_board[r][cursor_col + 2] = 'b'
            if new_cursor_col + 2 < 64:
                new_board[r][new_cursor_col] = 'S'
                new_board[r][new_cursor_col + 1] = 'S'
                new_board[r][new_cursor_col + 2] = 'S'

        # Check if blocks should move up (cursor was at column 30)
        blocks_shifted = (left_block_left != 21)

        if cursor_col == 30 and blocks_shifted:
            # Move left block up by 3
            for r in range(3, 64):
                for c in range(64):
                    if board[r][c] in 'cYb':
                        if board[r][c] == 'c':
                            new_board[r-3][c] = board[r][c]
                            new_board[r][c] = 'b'
                        elif board[r][c] == 'Y' and r >= left_block_top:
                            new_board[r-3][c] = board[r][c]
                            new_board[r][c] = 'b'
                        elif board[r][c] == 'b' and r >= left_block_top and c >= left_block_left - 6:
                            new_board[r-3][c] = board[r][c]
                            new_board[r][c] = 'b'

            # Move right block up by 3
            for r in range(3, 64):
                for c in range(64):
                    if board[r][c] in 'BW':
                        if board[r][c] == 'B' and r >= right_block_top:
                            new_board[r-3][c] = board[r][c]
                            new_board[r][c] = 'b'
                        elif board[r][c] == 'W' and r >= right_block_top:
                            new_board[r-3][c] = board[r][c]
                            new_board[r][c] = 'b'

        return [''.join(row) for row in new_board]

    elif action == 'LEFT':
        # Move cursor left by 3
        new_cursor_col = max(0, cursor_col - 3)

        # Create new board with background
        new_board = [['b' for _ in range(64)] for _ in range(64)]

        # Copy edge column (rightmost)
        for r in range(64):
            new_board[r][63] = board[r][63]

        # Copy bottom row
        for c in range(64):
            new_board[63][c] = board[63][c]

        # Copy blocks (shifted left by 6)
        for r in range(64):
            for c in range(6, 64):
                ch = board[r][c]
                # Left block cells
                if ch == 'c':
                    new_board[r][c-6] = ch
                elif ch == 'Y' and r >= left_block_top:
                    new_board[r][c-6] = ch
                elif ch == 'b' and r >= left_block_top and c >= left_block_left:
                    new_board[r][c-6] = ch
                # Right block cells
                elif ch == 'B' and r >= right_block_top:
                    new_board[r][c-6] = ch
                elif ch == 'W' and r >= right_block_top:
                    new_board[r][c-6] = ch
                elif ch == 'W' and r >= left_block_top and c >= left_block_left:
                    new_board[r][c-6] = ch

        # Copy cursor
        for r in range(64):
            if new_cursor_col + 2 < 64:
                new_board[r][new_cursor_col] = 'S'
                new_board[r][new_cursor_col + 1] = 'S'
                new_board[r][new_cursor_col + 2] = 'S'

        return [''.join(row) for row in new_board]

    elif action == 'RIGHT':
        # Move cursor right by 3
        new_cursor_col = min(61, cursor_col + 3)

        # Create new board with background
        new_board = [['b' for _ in range(64)] for _ in range(64)]

        # Copy edge column (rightmost)
        for r in range(64):
            new_board[r][63] = board[r][63]

        # Copy bottom row
        for c in range(64):
            new_board[63][c] = board[63][c]

        # Copy blocks (shifted right by 6)
        for r in range(64):
            for c in range(57, -1, -1):
                ch = board[r][c]
                # Left block cells
                if ch == 'c':
                    new_board[r][c+6] = ch
                elif ch == 'Y' and r >= left_block_top:
                    new_board[r][c+6] = ch
                elif ch == 'b' and r >= left_block_top and c >= left_block_left:
                    new_board[r][c+6] = ch
                # Right block cells
                elif ch == 'B' and r >= right_block_top:
                    new_board[r][c+6] = ch
                elif ch == 'W' and r >= right_block_top:
                    new_board[r][c+6] = ch
                elif ch == 'W' and r >= left_block_top and c >= left_block_left:
                    new_board[r][c+6] = ch

        # Copy cursor
        for r in range(64):
            if new_cursor_col + 2 < 64:
                new_board[r][new_cursor_col] = 'S'
                new_board[r][new_cursor_col + 1] = 'S'
                new_board[r][new_cursor_col + 2] = 'S'

        return [''.join(row) for row in new_board]

    elif action == 'SPACE':
        # Toggle white markers in cursor strip and blocks
        new_board = [row[:] for row in board]

        # Toggle W ↔ B in cursor strip (every 3rd row starting from row 1)
        for r in range(1, 64, 3):
            for c in range(cursor_col, cursor_col + 3):
                if c < 64:
                    if new_board[r][c] == 'W':
                        new_board[r][c] = 'B'
                    elif new_board[r][c] == 'B' and r > 0 and new_board[r-1][c] == 'S':
                        new_board[r][c] = 'W'

        # Toggle W ↔ B in blocks (every 3rd row starting from block top + 1)
        for r in range(left_block_top + 1, 64, 3):
            for c in range(64):
                if new_board[r][c] == 'W':
                    new_board[r][c] = 'B'
                elif new_board[r][c] == 'B' and c > 0 and new_board[r][c-1] == 'W':
                    new_board[r][c] = 'W'
                elif new_board[r][c] == 'B' and c < 63 and new_board[r][c+1] == 'W':
                    new_board[r][c] = 'W'

        for r in range(right_block_top + 1, 64, 3):
            for c in range(64):
                if new_board[r][c] == 'W':
                    new_board[r][c] = 'B'
                elif new_board[r][c] == 'B' and c > 0 and new_board[r][c-1] == 'W':
                    new_board[r][c] = 'W'
                elif new_board[r][c] == 'B' and c < 63 and new_board[r][c+1] == 'W':
                    new_board[r][c] = 'W'

        return [''.join(row) for row in new_board]

    elif action == 'UNDO':
        # No undo functionality observed
        return board_lines

    else:
        # MOUSE or unknown action - no change
        return board_lines

